import type { PlatformRole, UserSession } from '@pacom/contracts';
import { DEMO_ROLE_PROFILES, type PacomDataAdapter } from '../../adapters';

export function mountLoginView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  onAuthenticated: (session: UserSession) => void
): void {
  let errorMsg = '';
  let selectedRole: PlatformRole = 'facility_operator';

  function render(): void {
    const isDemo = adapter.mode === 'demo' && typeof adapter.switchDemoRole === 'function';
    root.innerHTML = `
      <main class="pacom-auth-page">
        <section class="pacom-auth-card" aria-label="PACOM Station 登录">
          <div>
            <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px;">
              <img src="/media/favicon.svg" alt="" width="24" height="24" />
              <span class="pacom-badge ${adapter.mode === 'live' ? 'pacom-badge--online' : 'pacom-badge--accent'}">
                ${adapter.mode.toUpperCase()} 模式
              </span>
            </div>
            <h1 class="pacom-auth-title">登录 PACOM Station</h1>
            <p style="margin:4px 0 0; color:var(--pacom-text-secondary); font-size:13px;">
              智能建筑空间运维与设备控制平台（E7F 生产底座）
            </p>
          </div>

          ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}

          <form data-role="login-form" style="display:flex; flex-direction:column; gap:12px;">
            <label class="pacom-field">
              <span>账号</span>
              <input class="pacom-input" name="account" placeholder="例如 operator@pacom.local" autocomplete="username" required />
            </label>
            <label class="pacom-field">
              <span>密码</span>
              <input class="pacom-input" name="password" type="password" placeholder="请输入密码" autocomplete="current-password" required />
            </label>
            <button class="pacom-btn pacom-btn--primary" type="submit" style="height:36px;">登录进入工作区</button>
          </form>

          ${
            isDemo
              ? `
              <div style="border-top: var(--hw) solid var(--pacom-border-subtle); padding-top:14px; display:flex; flex-direction:column; gap:10px;">
                <div style="font-size:13px; font-weight:500;">离线演示快捷入口（多角色 RBAC 权限预览）</div>
                <select class="pacom-select" data-role="demo-role-select" style="height:36px;">
                  ${(Object.keys(DEMO_ROLE_PROFILES) as PlatformRole[])
                    .map((role) => {
                      const profile = DEMO_ROLE_PROFILES[role];
                      return `<option value="${role}" ${role === selectedRole ? 'selected' : ''}>${profile.roleLabel} · ${profile.displayName}</option>`;
                    })
                    .join('')}
                </select>
                <button class="pacom-btn" type="button" data-role="enter-demo" style="height:36px;">
                  以所选角色进入 E7F 演示工作区
                </button>
              </div>`
              : ''
          }
        </section>
      </main>
    `;

    root.querySelector<HTMLFormElement>('[data-role="login-form"]')?.addEventListener('submit', async (e) => {
      e.preventDefault();
      const form = new FormData(e.currentTarget as HTMLFormElement);
      try {
        const session = await adapter.login({
          account: String(form.get('account') ?? ''),
          password: String(form.get('password') ?? ''),
        });
        onAuthenticated(session);
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });

    root.querySelector<HTMLSelectElement>('[data-role="demo-role-select"]')?.addEventListener('change', (e) => {
      selectedRole = (e.currentTarget as HTMLSelectElement).value as PlatformRole;
    });

    root.querySelector<HTMLButtonElement>('[data-role="enter-demo"]')?.addEventListener('click', async () => {
      if (!adapter.switchDemoRole) return;
      const session = await adapter.switchDemoRole(selectedRole);
      onAuthenticated(session);
    });
  }

  render();
}
