import './design-system/tokens.css';
import './design-system/app-shell.css';
import './design-system/nav-shell.css';
import { createDataAdapter } from './adapters';
import { mountAppShell } from './app/shell';
import { mountLoginView } from './features/auth/login-view';

async function bootstrap(): Promise<void> {
  const root = document.getElementById('app');
  if (!root) return;

  try {
    const adapter = createDataAdapter();
    const session = await adapter.getSession();

    const enterApp = async (activeSession: NonNullable<typeof session>) => {
      if (!window.location.hash || window.location.hash === '#login') {
        window.location.hash = '#home';
      }
      await mountAppShell(root, adapter, activeSession, () => {
        mountLoginView(root, adapter, (nextSession) => {
          void enterApp(nextSession);
        });
      });
    };

    if (!session || window.location.hash === '#login') {
      mountLoginView(root, adapter, (nextSession) => {
        void enterApp(nextSession);
      });
      return;
    }

    await enterApp(session);
  } catch (err) {
    root.innerHTML = `<div class="pacom-shell"><div class="pacom-alert-banner">初始化失败：${String(err)}</div></div>`;
  }
}

void bootstrap();
